// Tank pump on two float switches
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
int state = 0; // 0 idle, 1 pumping

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool lowFloat = P1.readDiscrete(inSlot, 1);
  bool highFloat = P1.readDiscrete(inSlot, 2);
  if (state == 0) {
    if (lowFloat && !highFloat) state = 1;
  } else if (state == 1) {
    if (highFloat) state = 0;
  }
  bool pumpRunning = (state == 1) && !highFloat;
  P1.writeDiscrete(pumpRunning, outSlot, 1);
}

// Tank pump on two float switches
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
enum PumpState { IDLE, RUNNING };
PumpState state = IDLE;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool lowFloat = P1.readDiscrete(inSlot, 1);
  bool highFloat = P1.readDiscrete(inSlot, 2);
  switch (state) {
    case IDLE:
      if (lowFloat && !highFloat) state = RUNNING;
      break;
    case RUNNING:
      if (highFloat) state = IDLE;
      break;
  }
  P1.writeDiscrete(state == RUNNING, outSlot, 1);
}

