// Tank pump on two float switches
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool pumpRunning = false;
int lowCount = 0;
int highCount = 0;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool lowFloat = P1.readDiscrete(inSlot, 1);
  bool highFloat = P1.readDiscrete(inSlot, 2);
  if (lowFloat) { if (lowCount < 5) lowCount++; } else lowCount = 0;
  if (highFloat) { if (highCount < 5) highCount++; } else highCount = 0;
  if (lowCount >= 5) pumpRunning = true;
  if (highCount >= 5) pumpRunning = false;
  P1.writeDiscrete(pumpRunning, outSlot, 1);
}

