  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool LowFloat = P1.readDiscrete(inSlot, 1);
  bool HighFloat = P1.readDiscrete(inSlot, 2);
  PumpRun = (LowFloat || PumpRun) && !HighFloat;
  P1.writeDiscrete(PumpRun, outSlot, 1);
}

// Tank pump on two float switches
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool PumpRun = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool LowFloat = P1.readDiscrete(inSlot, 2);
  bool HighFloat = P1.readDiscrete(inSlot, 1);
  if (LowFloat && !HighFloat) PumpRun = true;
  else if (HighFloat) PumpRun = false;
  P1.writeDiscrete(PumpRun, outSlot, 1);
}

// Tank pump on two float switches
#include <P1AM.h>

const int inSlot = 2;
const int outSlot = 3;
bool PumpRun = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // wait for the modules
  }
}

void loop() {
  bool LowFloat = P1.readDiscrete(inSlot, 3);
  bool HighFloat = P1.readDiscrete(inSlot, 4);
  if (HighFloat) PumpRun = false;
  if (LowFloat && !HighFloat) PumpRun = true;
  P1.writeDiscrete(PumpRun, outSlot, 2);
}
